<script lang="ts">
 import Header from './components/Header.svelte'; import FilterSidebar from './components/FilterSidebar.svelte'; import ParkMap from './components/ParkMap.svelte'; import ParkDetails from './components/ParkDetails.svelte'; import MunicipalityView from './components/MunicipalityView.svelte'; import {mockParks} from './data/mockParks'; import {defaultFilters,filterParks} from './lib/filterParks'; import type {Park,ParkFilters} from './types/park';
 let filters:ParkFilters=$state({...defaultFilters});let pinnedId:string|null=$state(null);let hovered:Park|null=$state(null);let filtersOpen=$state(false);let activeView:'find'|'municipality'=$state('find');let matches=$derived(filterParks(mockParks,filters));let pinned=$derived(matches.find(p=>p.id===pinnedId)??null);let displayPark=$derived(pinned??hovered);$effect(()=>{if(pinnedId&&!matches.some(p=>p.id===pinnedId))pinnedId=null;if(hovered&&!matches.some(p=>p.id===hovered?.id))hovered=null;});
</script>
<Header {activeView} onChangeView={(view)=>{activeView=view;filtersOpen=false}} onOpenFilters={()=>filtersOpen=true}/>
{#if activeView==='find'}<div class="demo-banner"><span>Demo data</span> Fictional examples only — awaiting team CSV</div><main><FilterSidebar bind:filters resultCount={matches.length} open={filtersOpen} onClose={()=>filtersOpen=false}/><section class="map-column">{#if matches.length===0}<div class="no-results"><div>⌁</div><h2>No parks match every filter</h2><p>Try clearing one or more requirements to widen your search.</p><button onclick={()=>filters={...defaultFilters}}>Clear all filters</button></div>{/if}<ParkMap parks={matches} selectedId={pinnedId} onHover={(p)=>{if(!pinnedId)hovered=p}} onLeave={()=>{if(!pinnedId)hovered=null}} onSelect={(p:Park)=>{pinnedId=p.id;hovered=null}}/></section><ParkDetails park={displayPark} pinned={pinned!==null} onClose={()=>{pinnedId=null;hovered=null}}/></main>{:else}<MunicipalityView drawerOpen={filtersOpen} onCloseDrawer={()=>filtersOpen=false}/>{/if}
